function getCore() {
  core ??= (async () => {
    const [{ createHighlighterCore }, { createJavaScriptRegexEngine }] = await Promise.all([
      import("shiki/core"),
      import("shiki/engine/javascript"),
    ])
    const highlighter = await createHighlighterCore({
      themes: [chatcnTheme],
      langs: [],
      engine: createJavaScriptRegexEngine({ forgiving: true }),
    })
    ready = highlighter
    return highlighter
  })()
  return core
}

/**
 * Loads Shiki and one grammar. Resolves `true` when the language can be highlighted, `false`
 * when it is unknown (the block then stays plain, which is the right fallback).
 */
function loadLanguage(lang?: string | null): Promise<boolean> {
  const id = resolveLanguage(lang)
  if (PLAIN.has(id) || missing.has(id)) return Promise.resolve(false)
  if (loaded.has(id) && ready) return Promise.resolve(true)
  const existing = pending.get(id)
  if (existing) return existing
  const task = (async () => {
    try {
      const [highlighter, { bundledLanguages, bundledLanguagesAlias }] = await Promise.all([
        getCore(),
        import("shiki/langs"),
      ])
      const input =
        (bundledLanguages as Record<string, unknown>)[id] ??
        (bundledLanguagesAlias as Record<string, unknown>)[id]
      if (!input) {
        missing.add(id)
        return false
      }
      await highlighter.loadLanguage(input as Parameters<HighlighterCore["loadLanguage"]>[0])
      loaded.add(id)
      return true
    } catch {
      missing.add(id)
      return false
    } finally {
      pending.delete(id)
    }
  })()
  pending.set(id, task)
  return task
}

/**
 * Incremental tokenizer for streaming code. Finished lines are tokenized once and kept (same
 * array identity, so memoized line components never re-render); only the line being written is
 * re-tokenized on each update, continuing from the saved grammar state.
 */
interface ChatcnLineTokenizer {
  update(code: string): ChatcnTokenLine[] | null
  reset(): void
}

/** Plain lines, used before the grammar loads and for unknown languages. */
function plainLines(code: string): ChatcnTokenLine[] {
  return code.split("\n").map((content) => (content ? [{ content, role: "plain" as const }] : []))
}

const ROLE = /--chatcn-code-([a-z]+)/

/* -------------------------------------------------------------------------------------------------
 * Tokenizing
 * -----------------------------------------------------------------------------------------------*/

function toLine(tokens: ThemedToken[] | undefined): ChatcnTokenLine {
  const line: ChatcnTokenLine = []
  for (const token of tokens ?? []) {
    const match = token.color ? ROLE.exec(token.color) : null
    const tokenRole = (match?.[1] as ChatcnTokenRole | undefined) ?? "plain"
    const last = line.at(-1)
    // Merge neighbours with the same role: fewer spans, same look.
    if (last && last.role === tokenRole) last.content += token.content
    else line.push({ content: token.content, role: tokenRole })
  }
  return line
}

function createLineTokenizer(lang?: string | null): ChatcnLineTokenizer {
  const id = resolveLanguage(lang)
  let stableCode = ""
  let stable: ChatcnTokenLine[] = []
  let state: GrammarState | undefined

  const reset = () => {
    stableCode = ""
    stable = []
    state = undefined
  }

  const run = (code: string) => {
    if (!ready) return { tokens: [] as ThemedToken[][], grammarState: undefined }
    return ready.codeToTokens(code, {
      lang: id,
      theme: "chatcn",
      ...(state ? { grammarState: state } : {}),
    })
  }

  return {
    reset,
    update(code) {
      if (PLAIN.has(id) || missing.has(id)) return plainLines(code)
      if (!ready || !loaded.has(id)) return null
      try {
        if (!code.startsWith(stableCode)) reset()
        const rest = code.slice(stableCode.length)
        const lastBreak = rest.lastIndexOf("\n")
        if (lastBreak >= 0) {
          const done = rest.slice(0, lastBreak)
          const result = run(done)
          stable = [...stable, ...result.tokens.map(toLine)]
          state = result.grammarState
          stableCode += rest.slice(0, lastBreak + 1)
        }
        const tail = code.slice(stableCode.length)
        const tailLine = tail ? toLine(run(tail).tokens[0]) : []
        return [...stable, tailLine]
      } catch {
        return plainLines(code)
      }
    },
  }
}

/** Tokenizes a whole snippet. Returns `null` until the language is ready. */
function tokenize(code: string, lang?: string | null): ChatcnTokenLine[] | null {
  const id = resolveLanguage(lang)
  if (PLAIN.has(id) || missing.has(id)) return plainLines(code)
  if (!ready || !loaded.has(id)) return null
  try {
    return ready.codeToTokens(code, { lang: id, theme: "chatcn" }).tokens.map(toLine)
  } catch {
    return plainLines(code)
  }
}

/**
 * Tokenizes code with the shared lazy Shiki. Renders plain lines first, then swaps to highlighted
 * lines on the frame the grammar is ready. Same text, same metrics: the swap never moves layout.
 * While `streaming`, only the line being written is re-tokenized on each update.
 */
function useChatcnHighlight(
  code: string,
  language?: string,
  { streaming = false }: { streaming?: boolean } = {},
): UseChatcnHighlightResult {
  const lang = resolveLanguage(language)
  const [, setVersion] = React.useState(0)
  const ready = isLanguageReady(lang)

  React.useEffect(() => {
    if (ready) return
    let alive = true
    void loadLanguage(lang).then(() => {
      if (alive) setVersion((v) => v + 1)
    })
    return () => {
      alive = false
    }
  }, [lang, ready])

  // One incremental tokenizer per language, kept across renders.
  const tokenizer = React.useMemo(() => createLineTokenizer(lang), [lang])

  return React.useMemo(() => {
    const lines = streaming ? tokenizer.update(code) : tokenize(code, lang)
    if (lines) return { lines, highlighted: ready }
    return { lines: plainLines(code), highlighted: false }
    // `ready` re-runs this once the grammar arrives.
  }, [code, lang, streaming, tokenizer, ready])
}

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

/** `"1,3-5"` or `[1, 3, 4, 5]` to a set of line numbers. */
function parseLineRanges(value: number[] | string | undefined): Set<number> {
  const out = new Set<number>()
  if (!value) return out
  if (Array.isArray(value)) {
    for (const n of value) out.add(n)
    return out
  }
  for (const part of value.split(",")) {
    const [a, b] = part.split("-").map((s) => Number.parseInt(s.trim(), 10))
    if (a === undefined || Number.isNaN(a)) continue
    const end = b === undefined || Number.isNaN(b) ? a : b
    for (let n = Math.min(a, end); n <= Math.max(a, end); n++) out.add(n)
  }
  return out
}

/* -------------------------------------------------------------------------------------------------
 * Lines
 * -----------------------------------------------------------------------------------------------*/

interface LineProps {
  tokens: ChatcnTokenLine
  number: number
  numbered: boolean
  marked: boolean
  caret: boolean
  /** Added or removed line in a `diff` fence. The +/- glyph stays as the non-color backup. */
  diff?: "add" | "del"
}

/** Each role reads one syntax variable. Keywords lead in red, comments and punctuation recede. */
const chatcnTokenClass: Record<ChatcnTokenRole, string> = {
  plain: "text-(color:--chatcn-syntax-plain)",
  keyword: "text-(color:--chatcn-syntax-keyword)",
  comment: "text-(color:--chatcn-syntax-comment)",
  string: "text-(color:--chatcn-syntax-string)",
  constant: "text-(color:--chatcn-syntax-constant)",
  function: "text-(color:--chatcn-syntax-function)",
  type: "text-(color:--chatcn-syntax-type)",
  tag: "text-(color:--chatcn-syntax-tag)",
  attribute: "text-(color:--chatcn-syntax-attribute)",
  punctuation: "text-(color:--chatcn-syntax-punctuation)",
}

type StreamingCaretStatus = "streaming" | "waiting" | "done"

interface StreamingCaretProps extends Omit<React.ComponentProps<"span">, "children"> {
  /**
   * `streaming` is solid, `waiting` blinks slowly, `done` removes the caret. Defaults to
   * `streaming`.
   */
  status?: StreamingCaretStatus
  /**
   * Pass the streamed text (or anything that changes with each token). While it keeps changing
   * the caret stays solid; once it holds still for `idleMs` the caret starts to blink.
   */
  activity?: unknown
  /** Quiet time before the caret switches to blinking. Defaults to 600 ms. */
  idleMs?: number
}

/**
 * The signature mark: a small rounded square that means "the model is writing here". It sits on
 * the text baseline at 0.55em, so it scales with whatever text it follows. Solid while tokens flow,
 * a slow 1.2 s blink only while waiting, gone when done. Static under reduced motion.
 */
function StreamingCaret({
  status = "streaming",
  activity,
  idleMs = 600,
  className,
  ...props
}: StreamingCaretProps) {
  const [idle, setIdle] = React.useState(false)
  const tracking = activity !== undefined && status === "streaming"

  React.useEffect(() => {
    if (!tracking) return
    setIdle(false)
    const id = window.setTimeout(() => setIdle(true), idleMs)
    return () => window.clearTimeout(id)
  }, [activity, tracking, idleMs])

  if (status === "done") return null
  const blinking = status === "waiting" || (tracking && idle)

  return (
    <span
      aria-hidden="true"
      data-slot="streaming-caret"
      data-caret-state={blinking ? "waiting" : "streaming"}
      className={cn(
        "bg-(color:--chatcn-accent) ms-0.5 inline-block size-[0.55em] translate-y-[0.04em] rounded-[0.12em] align-baseline forced-colors:bg-[CanvasText]",
        blinking &&
          "animate-[chatcn-caret-blink_1.2s_steps(1,end)_infinite] motion-reduce:animate-none",
        className,
      )}
      {...props}
    />
  )
}

const sameLine = (a: ChatcnTokenLine, b: ChatcnTokenLine) =>
  a === b ||
  (a.length === b.length && a.every((t, i) => t.content === b[i]?.content && t.role === b[i]?.role))

// Finished lines keep their props, so a streaming block only re-renders the line being written.
const Line = React.memo(
  function Line({ tokens, number, numbered, marked, caret, diff }: LineProps) {
    return (
      <span
        data-line={number}
        data-highlighted={marked ? "" : undefined}
        data-diff={diff}
        className={cn(
          // The block's surface is inherited all the way down and tints are painted over it, so
          // the sticky gutter is opaque and code never shows through it when scrolled sideways.
          "flex min-h-5 bg-inherit",
          (diff || marked) && "bg-[linear-gradient(var(--row),var(--row))]",
          diff === "add" && "[&_span]:text-(color:--chatcn-diff-add-fg) [--row:var(--chatcn-diff-add-bg)]",
          diff === "del" && "[&_span]:text-(color:--chatcn-diff-del-fg) [--row:var(--chatcn-diff-del-bg)]",
          marked && "shadow-[inset_2px_0_0_var(--chatcn-fg-subtle)] [--row:var(--chatcn-fill)]",
        )}
      >
        {numbered ? (
          <span
            aria-hidden="true"
            className={cn(
              "sticky start-0 shrink-0 bg-inherit [background-image:inherit] ps-4 pe-4 text-end tabular-nums [box-shadow:inherit] select-none",
              "w-[calc(var(--chatcn-code-digits)*1ch+2rem)]",
              marked ? "text-(color:--chatcn-fg-muted)" : "text-(color:--chatcn-fg-subtle)",
            )}
          >
            {number}
          </span>
        ) : null}
        <span className={cn("min-w-0 flex-1 pe-4", !numbered && "ps-4")}>
          {tokens.map((token, i) => (
            <span key={i} className={chatcnTokenClass[token.role]}>
              {token.content}
            </span>
          ))}
          {caret ? <StreamingCaret /> : null}
        </span>
      </span>
    )
  },
  (a, b) =>
    a.number === b.number &&
    a.numbered === b.numbered &&
    a.marked === b.marked &&
    a.caret === b.caret &&
    a.diff === b.diff &&
    sameLine(a.tokens, b.tokens),
)

/** In a `diff` fence, `+` and `-` lines (not the `+++` and `---` file headers) get a tint. */
function diffKind(tokens: ChatcnTokenLine): LineProps["diff"] {
  const text = tokens.map((t) => t.content).join("")
  if (text.startsWith("+") && !text.startsWith("+++")) return "add"
  if (text.startsWith("-") && !text.startsWith("---")) return "del"
  return undefined
}

