/**
 * An agent adds retries to a checkout: each file it touches lights up in the tree with its
 * status and line counts, the selection follows it, and the file opens beside the tree. Loops.
 * Pick a file yourself and the tour waits a moment on it.
 */
export default function FileTreePreview() {
  const [beat, setBeat] = React.useState(1)
  const [held, hold] = useHold()
  const [mine, setMine] = React.useState<string | null>(null)

  React.useEffect(() => {
    if (reducedMotion()) {
      setBeat(CHANGES.length)
      return
    }
    if (held) return
    const id = window.setInterval(
      () => setBeat((b) => (b + 1) % (CHANGES.length + REST_BEATS)),
      BEAT_MS,
    )
    return () => window.clearInterval(id)
  }, [held])

  const count = Math.min(CHANGES.length, beat + 1)
  const nodes = React.useMemo(() => treeAt(count), [count])
  const touched = CHANGES[count - 1]!
  const selected = held && mine ? mine : touched.path
  const shown = CHANGES.find((c) => c.path === selected)

  return (
    <FitFrame minWidth="50rem">
      <div className="flex w-full flex-col items-center justify-center gap-4 p-6">
        <div className="grid h-[22.5rem] w-full max-w-3xl grid-cols-[17rem_1fr] gap-3">
          <div className="rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) flex flex-col overflow-hidden">
            <div className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex items-center justify-between px-3 pt-2.5 pb-1">
              <span>Changes</span>
              <span className="tabular-nums">{count} files</span>
            </div>
            <FileTree
              nodes={nodes}
              defaultExpanded={OPEN}
              selected={selected}
              onSelectedChange={(path) => {
                hold()
                setMine(path)
              }}
              label="Files the agent changed"
            />
          </div>
          <div className="flex min-w-0 flex-col [--chatcn-code-sticky-top:-100rem]">
            <CodeBlock
              className="h-full"
              filename={selected}
              language={languageOf(selected)}
              code={shown?.code ?? `// ${selected}\n// No changes in this file.`}
            />
          </div>
        </div>
        <MoreOn slug="file-tree">Change markers, line counts and keyboard navigation. On</MoreOn>
      </div>
    </FitFrame>
  )
}
